<template>
  <div class="d-center">
    <el-form
      :model="addform"
      :rules="rules"
      ref="addform"
      label-width="130px"
      class="demo-ruleForm mt-30"
      style="width: 40%"
      :validate-on-rule-change="false"
    >
      <el-form-item label="网络号:" prop="pan_id">
        <el-input-number v-model="addform.pan_id" />
      </el-form-item>
      <el-form-item label="通道号:" prop="channel_num">
        <el-select v-model="addform.channel_num">
          <el-option
            v-for="item in channelList"
            :key="item"
            :label="item"
            :value="item"
          ></el-option>
        </el-select>
      </el-form-item>
      <!-- <el-form-item label="串口列表:" prop="interface_name">
        <el-select v-model="addform.interface_name">
          <el-option
            :label="item"
            :value="item"
            v-for="(item, index) in interfaceList"
            :key="index"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="波特率:" prop="baudrate">
        <el-select v-model="addform.baudrate">
          <el-option
            :label="item"
            :value="item"
            v-for="(item, index) in baudrateList"
            :key="index"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="网络号设置:" prop="pan_id">
        <el-input-number v-model="addform.pan_id" />
      </el-form-item>
      <el-form-item label="通道号设置:" prop="channel_num">
        <el-select v-model="addform.channel_num">
          <el-option
            v-for="item in channelList"
            :key="item"
            :label="item"
            :value="item"
          ></el-option>
        </el-select>
      </el-form-item>
     -->

      <el-form-item>
        <el-button
          style="width: 100%"
          type="primary"
          @click="submitForm('addform')"
        >
          保存
        </el-button>
      </el-form-item>
    </el-form>
  </div>
</template>

<script>
export default {
  data() {
    function validate31(rule, value, callback) {
      const port = parseInt(value, 10);
      let isPort = Number.isInteger(port) && port >= 0 && port <= 65535;
      if (!isPort) {
        callback(new Error("请输入0-65531范围内的数"));
      } else {
        callback();
      }
    }
    let validate35 = (rule, value, callback) => {
      const reg =
        /^(?:[0-9]|[1-9][0-9]|[1-9][0-9][0-9]|[1-9][0-9][0-9][0-9]|6[0-4][0-9][0-9]|65[0-4][0-9]|655[0-2][0-9]|6553[0-5])$/;
      if (!reg.test(value) && !reg.test(value)) {
        callback(new Error("请输入0-65535范围内的数"));
      } else {
        callback();
      }
    };
    return {
      addform: {
        redial: false,
      },
      rules: {
        pan_id: [
          {
            required: true,
            message: "请输入",
            trigger: ["blur", "change"],
          },
          { validator: validate31, trigger: ["blur", "change"] },
        ],
        channel_num: [
          {
            required: true,
            message: "请输入",
            trigger: ["blur", "change"],
          },
        ],
        cluster_id: [
          {
            required: true,
            message: "请输入",
            trigger: ["blur", "change"],
          },
          { validator: validate35, trigger: ["blur", "change"] },
        ],
      },
      loading: false,
      protocol_type: 1,
      channelList: [],
      interfaceList: [],
      baudrateList: [2400, 4800, 9600, 19200, 38400, 57600, 115200],
    };
  },
  created() {
    for (let i = 11; i <= 26; i++) {
      this.channelList.push(i);
    }
    this.getData();
    this.getInterfaceList();
  },
  methods: {
    getInterfaceList() {
      this.$api.get("/collect/getSerialPortList").then((res) => {
        this.interfaceList = res.data.data;
      });
    },
    async getData() {
      try {
        const res = await this.$api.get("/net/getZigbee");
        let data = res.data.data;
        if (data) {
          this.addform = data;
        } else {
          this.addform = {};
          this.$nextTick(() => {
            this.$refs.addform.clearValidate();
          });
        }
        return true;
      } catch (error) {
        console.error("获取失败:", error);
        return false;
      }
    },

    async submitForm(formName) {
      try {
        console.log(this.addform);

        const valid = await this.$refs[formName].validate();
        if (!valid) return;
        this.loading = true;
        await this.$api.post("/net/updateZigbee", this.addform);
        this.$message.success("操作成功");
        this.getData();
      } catch (error) {
        console.error("启动检测失败:", error);
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

<style scoped>
.mt-30 {
  margin-top: 30px;
}
</style>
